,p_subscribe_plugin_settings=>true
,p_help_text=>'Pick a Style for the region. Map State to a column or static value returning success, warning, danger, info or neutral; any other value renders as neutral. Danger alerts use role=alert, all others role=status. Icon defaults to a state icon when left empty. The link renders only when both Link URL and Link Label are set.'
,p_version_identifier=>'1.0.1'
,p_files_version=>1
);
